-- aicloud business schema, independently derived from public MIT entity mappings.
USE aicloud;
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS `trade_after_sale` (
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `creator` varchar(64) DEFAULT '',
  `updater` varchar(64) DEFAULT '',
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `id` bigint NOT NULL AUTO_INCREMENT,
  `no` text,
  `status` int DEFAULT 0,
  `way` int DEFAULT 0,
  `type` int DEFAULT 0,
  `user_id` bigint DEFAULT 0,
  `apply_reason` text,
  `apply_description` text,
  `apply_pic_urls` json DEFAULT NULL,
  `order_id` bigint DEFAULT 0,
  `order_no` varchar(255) DEFAULT NULL,
  `order_item_id` bigint DEFAULT 0,
  `spu_id` bigint DEFAULT 0,
  `spu_name` varchar(255) DEFAULT NULL,
  `sku_id` bigint DEFAULT 0,
  `properties` json DEFAULT NULL,
  `pic_url` text,
  `count` int DEFAULT 0,
  `audit_time` datetime DEFAULT NULL,
  `audit_user_id` bigint DEFAULT 0,
  `audit_reason` text,
  `refund_price` int DEFAULT 0,
  `pay_refund_id` bigint DEFAULT 0,
  `refund_time` datetime DEFAULT NULL,
  `logistics_id` bigint DEFAULT 0,
  `logistics_no` varchar(255) DEFAULT NULL,
  `delivery_time` datetime DEFAULT NULL,
  `receive_time` datetime DEFAULT NULL,
  `receive_reason` text,
  `tenant_id` bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_order_item_id` (`order_item_id`),
  KEY `idx_spu_id` (`spu_id`),
  KEY `idx_sku_id` (`sku_id`),
  KEY `idx_audit_user_id` (`audit_user_id`),
  KEY `idx_pay_refund_id` (`pay_refund_id`),
  KEY `idx_logistics_id` (`logistics_id`),
  KEY `idx_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

