  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `creator` varchar(64) DEFAULT '',
  `updater` varchar(64) DEFAULT '',
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `id` bigint NOT NULL AUTO_INCREMENT,
  `send_record_id` bigint DEFAULT 0,
  `month_employee_record_id` bigint DEFAULT 0,
  `employee_id` bigint DEFAULT 0,
  `year` int DEFAULT 0,
  `month` int DEFAULT 0,
  `read_status` int DEFAULT 0,
  `real_pay_salary` decimal(24,8) DEFAULT 0,
  `remark` text,
  `options` json DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_send_record_id` (`send_record_id`),
  KEY `idx_month_employee_record_id` (`month_employee_record_id`),
  KEY `idx_employee_id` (`employee_id`),
  KEY `idx_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `hrm_salary_slip_send_record` (
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `creator` varchar(64) DEFAULT '',
  `updater` varchar(64) DEFAULT '',
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `id` bigint NOT NULL AUTO_INCREMENT,
  `month_record_id` bigint DEFAULT 0,
  `employee_count` int DEFAULT 0,
  `send_employee_count` int DEFAULT 0,
  `year` int DEFAULT 0,
  `month` int DEFAULT 0,
  `tenant_id` bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_month_record_id` (`month_record_id`),
  KEY `idx_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `hrm_salary_slip_template` (
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `creator` varchar(64) DEFAULT '',
  `updater` varchar(64) DEFAULT '',
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(255) DEFAULT NULL,
  `hide_empty` bit(1) DEFAULT b'0',
  `default_status` bit(1) DEFAULT b'0',
  `options` json DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `hrm_salary_tax_rule` (
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `creator` varchar(64) DEFAULT '',
  `updater` varchar(64) DEFAULT '',
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(255) DEFAULT NULL,
  `type` int DEFAULT 0,
  `tax_enabled` bit(1) DEFAULT b'0',
  `threshold` decimal(24,8) DEFAULT 0,
  `decimal_scale` int DEFAULT 0,
  `cycle_type` int DEFAULT 0,
  `tenant_id` bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

